import app from 'flarum/admin/app';
const t = k => app.translator.trans('ernestdefoe-roster.admin.' + k);
app.initializers.add('ernestdefoe-roster', () => {
  app.extensionData.for('ernestdefoe-roster').registerSetting(function () {
    /*
     * 🚨 The league list comes from the SERVER's registry, never from a copy
     * written here. A second list in the bundle goes stale the first time an
     * extension registers a competition.
     *
     * 🚨 College football is deliberately absent: it is not optional and it
     * is not ESPN's. Offering it as a tick box would suggest it can be
     * switched off here.
     */
    const registry = app.data?.rosterLeagues ?? {};
    const chosen = String(app.data.settings['ernestdefoe-roster.leagues'] || '').split(',').map(s => s.trim()).filter(Boolean);
    const toggle = (key, on) => {
      const next = on ? [...new Set([...chosen, key])] : chosen.filter(k => k !== key);
      app.data.settings['ernestdefoe-roster.leagues'] = next.join(',');
      m.redraw();
    };
    return m("div", {
      className: "Form-group"
    }, m("label", null, t('leagues_label')), m("div", {
      className: "helpText"
    }, t('leagues_help')), Object.keys(registry).filter(key => key !== 'cfb').map(key => m("label", {
      className: "checkbox"
    }, m("input", {
      type: "checkbox",
      checked: chosen.includes(key),
      onchange: e => toggle(key, e.target.checked)
    }), registry[key])));
  });
});